from pathlib import Path

# Extend the private Accounts summary endpoint with daily acquisition data.
path = Path('subscriptionAdminDashboardRoutes.js')
text = path.read_text()

old = """    const [summaryResult, monthlyResult] = await Promise.all(["""
new = """    const [summaryResult, monthlyResult, dailyResult] = await Promise.all(["""
assert old in text, 'accounts summary Promise.all marker not found'
text = text.replace(old, new, 1)

old = """          COUNT(*) FILTER (\n            WHERE to_char(created_at AT TIME ZONE 'America/Chicago', 'YYYY-MM') =\n                  to_char(NOW() AT TIME ZONE 'America/Chicago', 'YYYY-MM')\n          )::int AS created_this_month\n        FROM accounts\n"""
new = """          COUNT(*) FILTER (\n            WHERE to_char(created_at AT TIME ZONE 'America/Chicago', 'YYYY-MM') =\n                  to_char(NOW() AT TIME ZONE 'America/Chicago', 'YYYY-MM')\n          )::int AS created_this_month,\n          COUNT(*) FILTER (\n            WHERE (created_at AT TIME ZONE 'America/Chicago')::date =\n                  (NOW() AT TIME ZONE 'America/Chicago')::date\n          )::int AS created_today,\n          COUNT(*) FILTER (\n            WHERE (created_at AT TIME ZONE 'America/Chicago')::date >=\n                  (NOW() AT TIME ZONE 'America/Chicago')::date - 6\n          )::int AS created_last_7_days,\n          COUNT(*) FILTER (\n            WHERE (created_at AT TIME ZONE 'America/Chicago')::date >=\n                  (NOW() AT TIME ZONE 'America/Chicago')::date - 13\n              AND (created_at AT TIME ZONE 'America/Chicago')::date <\n                  (NOW() AT TIME ZONE 'America/Chicago')::date - 6\n          )::int AS created_previous_7_days\n        FROM accounts\n"""
assert old in text, 'accounts summary SQL marker not found'
text = text.replace(old, new, 1)

old = """      historyPool.query(`\n        SELECT\n          to_char(created_at AT TIME ZONE 'America/Chicago', 'YYYY-MM') AS month,\n          COUNT(*)::int AS created_accounts\n        FROM accounts\n        GROUP BY 1\n        ORDER BY 1\n      `),\n    ]);\n"""
new = """      historyPool.query(`\n        SELECT\n          to_char(created_at AT TIME ZONE 'America/Chicago', 'YYYY-MM') AS month,\n          COUNT(*)::int AS created_accounts\n        FROM accounts\n        GROUP BY 1\n        ORDER BY 1\n      `),\n      historyPool.query(`\n        WITH days AS (\n          SELECT generate_series(\n            (NOW() AT TIME ZONE 'America/Chicago')::date - 89,\n            (NOW() AT TIME ZONE 'America/Chicago')::date,\n            INTERVAL '1 day'\n          )::date AS day\n        ), counts AS (\n          SELECT\n            (created_at AT TIME ZONE 'America/Chicago')::date AS day,\n            COUNT(*)::int AS created_accounts\n          FROM accounts\n          WHERE (created_at AT TIME ZONE 'America/Chicago')::date >=\n                (NOW() AT TIME ZONE 'America/Chicago')::date - 89\n          GROUP BY 1\n        )\n        SELECT\n          to_char(days.day, 'YYYY-MM-DD') AS day,\n          COALESCE(counts.created_accounts, 0)::int AS created_accounts\n        FROM days\n        LEFT JOIN counts USING (day)\n        ORDER BY days.day\n      `),\n    ]);\n"""
assert old in text, 'monthly query marker not found'
text = text.replace(old, new, 1)

old = """      createdThisMonth: Number(summaryResult.rows[0]?.created_this_month || 0),\n      currentMonth:"""
new = """      createdThisMonth: Number(summaryResult.rows[0]?.created_this_month || 0),\n      createdToday: Number(summaryResult.rows[0]?.created_today || 0),\n      createdLast7Days: Number(summaryResult.rows[0]?.created_last_7_days || 0),\n      createdPrevious7Days: Number(summaryResult.rows[0]?.created_previous_7_days || 0),\n      currentDate: dailyResult.rows.at(-1)?.day || null,\n      currentMonth:"""
assert old in text, 'account response summary marker not found'
text = text.replace(old, new, 1)

old = """      months: monthlyResult.rows.map((row) => ({\n        month: row.month,\n        createdAccounts: Number(row.created_accounts || 0),\n      })),\n"""
new = """      days: dailyResult.rows.map((row) => ({\n        day: row.day,\n        createdAccounts: Number(row.created_accounts || 0),\n      })),\n      months: monthlyResult.rows.map((row) => ({\n        month: row.month,\n        createdAccounts: Number(row.created_accounts || 0),\n      })),\n"""
assert old in text, 'account response months marker not found'
text = text.replace(old, new, 1)
path.write_text(text)

# Add daily account acquisition UI while preserving the monthly view.
path = Path('lib/subscriptionAdminAccountsUi.js')
text = path.read_text()

old = """      `<div class=\"grid accounts-metrics\" id=\"accountMetrics\"><div class=\"loading\">Loading accounts...</div></div>\\n      <div class=\"section\">\\n        <div class=\"sectionhead\"><h2>Accounts created by month</h2><span id=\"accountsChartSummary\">New registered accounts</span></div>\\n        <div id=\"accountsChart\" class=\"accounts-chart\"><div class=\"loading\">Loading account creation history...</div></div>\\n      </div>\\n"""
new = """      `<div class=\"grid accounts-metrics\" id=\"accountMetrics\"><div class=\"loading\">Loading accounts...</div></div>\\n      <div class=\"section\">\\n        <div class=\"sectionhead accounts-daily-head\"><h2>Accounts created by day</h2><div class=\"accounts-daily-controls\"><span id=\"accountsDailySummary\">Daily registrations</span><div class=\"account-range\" role=\"group\" aria-label=\"Daily account chart range\"><button type=\"button\" data-account-range=\"7\">7D</button><button type=\"button\" class=\"active\" data-account-range=\"30\">30D</button><button type=\"button\" data-account-range=\"90\">90D</button></div></div></div>\\n        <div id=\"accountsDailyChart\" class=\"accounts-chart\"><div class=\"loading\">Loading daily account creation...</div></div>\\n      </div>\\n      <div class=\"section\">\\n        <div class=\"sectionhead\"><h2>Accounts created by month</h2><span id=\"accountsChartSummary\">New registered accounts</span></div>\\n        <div id=\"accountsChart\" class=\"accounts-chart\"><div class=\"loading\">Loading account creation history...</div></div>\\n      </div>\\n"""
assert old in text, 'Accounts section marker not found'
text = text.replace(old, new, 1)

old = """      `.accounts-metrics { grid-template-columns:repeat(3,minmax(0,1fr)); }\\n    .accounts-chart { padding:14px 18px 12px;min-height:300px;overflow-x:auto; }\\n    @media (max-width:900px){ .accounts-metrics{grid-template-columns:1fr 1fr} }\\n"""
new = """      `.accounts-metrics { grid-template-columns:repeat(4,minmax(0,1fr)); }\\n    .accounts-chart { padding:14px 18px 12px;min-height:300px;overflow-x:auto; }\\n    .accounts-daily-head { gap:16px;align-items:center; }\\n    .accounts-daily-controls { display:flex;align-items:center;gap:14px;flex-wrap:wrap;justify-content:flex-end; }\\n    .account-range { display:inline-flex;border:1px solid #2a2f39;border-radius:9px;padding:2px;background:#0d0f13; }\\n    .account-range button { border:0;background:transparent;color:#8d95a3;padding:5px 9px;border-radius:6px;font:inherit;font-size:11px;font-weight:750;cursor:pointer; }\\n    .account-range button:hover { color:#dfe4ec; }\\n    .account-range button.active { color:#d9efff;background:rgba(102,168,232,.16);box-shadow:inset 0 0 0 1px rgba(102,168,232,.24); }\\n    @media (max-width:1100px){ .accounts-metrics{grid-template-columns:1fr 1fr} }\\n"""
assert old in text, 'Accounts CSS marker not found'
text = text.replace(old, new, 1)

marker = """  function renderAccountsChart(){\\n"""
insert = r"""  let accountsDailyRange=30;\n  function accountDayLabel(key,includeYear=false){\n    const parts=String(key||'').split('-').map(Number);\n    if(parts.length!==3||!parts[0]||!parts[1]||!parts[2])return String(key||'');\n    return new Date(Date.UTC(parts[0],parts[1]-1,parts[2])).toLocaleDateString(undefined,{month:'short',day:'numeric',year:includeYear?'numeric':undefined,timeZone:'UTC'});\n  }\n  function accountDailyRows(range=accountsDailyRange){\n    return [...(accountsData?.days||[])].sort((a,b)=>String(a.day).localeCompare(String(b.day))).slice(-range);\n  }\n  function accountDailyComparison(){\n    const current=Number(accountsData?.createdLast7Days||0), previous=Number(accountsData?.createdPrevious7Days||0);\n    if(previous===0){\n      if(current===0)return 'No accounts created in the last 7 days';\n      return current+' in last 7 days · up from 0 in previous 7';\n    }\n    const pct=Math.round(((current-previous)/previous)*100);\n    return current+' in last 7 days · '+(pct===0?'no change':((pct>0?'+':'')+pct+'%'))+' vs previous 7';\n  }\n  function bindAccountDailyRange(){\n    qsa('[data-account-range]').forEach(button=>{\n      if(button.dataset.bound==='1')return; button.dataset.bound='1';\n      button.addEventListener('click',()=>{ accountsDailyRange=Number(button.dataset.accountRange||30); renderAccountsDailyChart(accountsDailyRange); });\n    });\n  }\n  function renderAccountsDailyChart(range=accountsDailyRange){\n    const el=qs('#accountsDailyChart'), summary=qs('#accountsDailySummary');\n    if(!el||!summary||!accountsData)return;\n    accountsDailyRange=range;\n    qsa('[data-account-range]').forEach(button=>button.classList.toggle('active',Number(button.dataset.accountRange)===range));\n    const rows=accountDailyRows(range);\n    summary.textContent=accountDailyComparison();\n    if(!rows.length){ el.innerHTML='<div class="empty">No daily account creation history yet.</div>'; return; }\n    const currentDate=String(accountsData.currentDate||rows[rows.length-1]?.day||'');\n    const width=Math.max(900,rows.length*22),height=270,left=54,right=22,top=24,bottom=48;\n    const plotWidth=width-left-right,plotHeight=height-top-bottom,baseY=top+plotHeight;\n    const maxValue=Math.max(1,...rows.map(row=>Number(row.createdAccounts||0)));\n    const slotWidth=plotWidth/Math.max(1,rows.length),barWidth=Math.max(7,Math.min(42,slotWidth*.62));\n    const xAt=index=>left+slotWidth*(index+.5),yAt=value=>top+plotHeight-(Number(value||0)/maxValue)*plotHeight;\n    const tickCount=Math.max(1,Math.min(5,maxValue));\n    const grid=Array.from({length:tickCount+1},(_,index)=>{ const value=Math.round(maxValue*index/tickCount),y=yAt(value); return '<line x1="'+left+'" y1="'+y.toFixed(1)+'" x2="'+(width-right)+'" y2="'+y.toFixed(1)+'" stroke="#242832" stroke-width="1"/><text x="'+(left-10)+'" y="'+(y+4).toFixed(1)+'" fill="#737b89" font-size="11" text-anchor="end">'+esc(value)+'</text>'; }).join('');\n    const labelEvery=range<=7?1:(range<=30?3:7);\n    const bars=rows.map((row,index)=>{ const value=Number(row.createdAccounts||0),x=xAt(index),y=yAt(value),active=row.day===currentDate,barHeight=Math.max(0,baseY-y),showLabel=index%labelEvery===0||index===rows.length-1; return '<g><rect x="'+(x-barWidth/2).toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+barWidth.toFixed(1)+'" height="'+barHeight.toFixed(1)+'" rx="'+Math.min(5,barWidth/2).toFixed(1)+'" fill="'+(active?'#8fc1ee':'#66a8e8')+'" opacity="'+(active?'1':'.78')+'"><title>'+esc(accountDayLabel(row.day,true)+': '+value+' account'+(value===1?'':'s')+' created')+'</title></rect>'+(value>0?'<text x="'+x.toFixed(1)+'" y="'+Math.max(14,y-7).toFixed(1)+'" fill="'+(active?'#f3f1eb':'#aeb4be')+'" font-size="10" font-weight="700" text-anchor="middle">'+esc(value)+'</text>':'')+(showLabel?'<text x="'+x.toFixed(1)+'" y="'+(height-17)+'" fill="'+(active?'#f3f1eb':'#737b89')+'" font-size="10" text-anchor="middle">'+esc(accountDayLabel(row.day))+'</text>':'')+'</g>'; }).join('');\n    el.innerHTML='<svg role="img" aria-label="Accounts created by day" viewBox="0 0 '+width+' '+height+'" style="display:block;width:100%;min-width:900px;height:auto">'+grid+bars+'</svg>';\n  }\n  function renderAccountsChart(){\n"""
assert marker in text, 'renderAccountsChart marker not found'
text = text.replace(marker, insert, 1)

old = """    const metrics=qs('#accountMetrics'), chart=qs('#accountsChart'), table=qs('#accountsTable');\\n    metrics.innerHTML='<div class=\"loading\">Loading accounts...</div>'; chart.innerHTML='<div class=\"loading\">Loading account creation history...</div>'; table.innerHTML='<div class=\"loading\">Loading account history...</div>';\\n"""
new = """    const metrics=qs('#accountMetrics'), dailyChart=qs('#accountsDailyChart'), chart=qs('#accountsChart'), table=qs('#accountsTable');\\n    metrics.innerHTML='<div class=\"loading\">Loading accounts...</div>'; dailyChart.innerHTML='<div class=\"loading\">Loading daily account creation...</div>'; chart.innerHTML='<div class=\"loading\">Loading account creation history...</div>'; table.innerHTML='<div class=\"loading\">Loading account history...</div>';\\n"""
assert old in text, 'loadAccounts loading marker not found'
text = text.replace(old, new, 1)

old = """      metrics.innerHTML=[\\n        metric('Current accounts',Number(accountsData.totalAccounts||0),'Registered accounts · deleted accounts excluded'),\\n        metric('Created this month',Number(accountsData.createdThisMonth||0),'New account registrations this month'),\\n        metric('All-time created',Number(accountsData.allTimeCreated||0),'Includes accounts that were later deleted')\\n      ].join('');\\n      renderAccountsChart();\\n"""
new = """      metrics.innerHTML=[\\n        metric('Current accounts',Number(accountsData.totalAccounts||0),'Registered accounts · deleted accounts excluded'),\\n        metric('Created today',Number(accountsData.createdToday||0),'New account registrations today'),\\n        metric('Created this month',Number(accountsData.createdThisMonth||0),'New account registrations this month'),\\n        metric('All-time created',Number(accountsData.allTimeCreated||0),'Includes accounts that were later deleted')\\n      ].join('');\\n      bindAccountDailyRange();\\n      renderAccountsDailyChart(accountsDailyRange);\\n      renderAccountsChart();\\n"""
assert old in text, 'Accounts metrics marker not found'
text = text.replace(old, new, 1)
path.write_text(text)

